 internal static UsbAdmissionWorkerBackend AcquireRetiredForExact(bool requireEmptyPolicy){
  var backend=new UsbAdmissionWorkerBackend();try{
   backend.exactEnrollmentPin=new UsbEnrollmentConfig(DirectoryPath);
   backend.CheckRetiredForExact();if(requireEmptyPolicy)backend.DemandEmptyPolicyAndNoUnownedOperations();backend.CheckRetiredForExact();return backend;
  }catch{backend.Dispose();throw;}
 }
